namespace sv_6d7b33f576ee42148543da2d4d0c40dd.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications =
    [
        new(0, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)),
    ];

    public NotificationService()
    {
        _nextId = 1;
    }

    /// <summary>Returns all notifications available right now.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications added after the given timestamp.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        // Simulate a new notification arriving roughly every 10 seconds.
        MaybeAddFakeNotification();

        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Timestamp > since).ToList());
        }
    }

    private void MaybeAddFakeNotification()
    {
        lock (_lock)
        {
            var last = _notifications.MaxBy(n => n.Timestamp);
            if (last is null || DateTime.UtcNow - last.Timestamp > TimeSpan.FromSeconds(10))
            {
                var id = _nextId++;
                _notifications.Add(new Notification(
                    id,
                    $"New event #{id} happened — check it out!",
                    DateTime.UtcNow));
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? notifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only hit the service when state was NOT restored from prerender.
        notifications ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender never fires during prerender, so this is safe
            // to start the background polling loop.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var since = notifications?.MaxBy(n => n.Timestamp)?.Timestamp ?? DateTime.MinValue;
            var newer = await NotificationService.GetNotificationsSinceAsync(since);

            if (newer.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications ??= [];
                    notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

